(7345006, 1148063, 115814, '<td valign="top">I''m a sucker for this type of vertical camera motion blur a la Orton. This is a standout with lovely contrasts, and compositional balance. A top pick from me!</td>', 'I''m a sucker for this type of vertical camera motion blur a la Orton. This is a standout with lovely contrasts, and compositional balance. A top pick from me!', '2015-04-24 11:52:28.000000', NULL, 1),
(7345007, 1148126, 115814, '<td valign="top">Stunning. Confusion and disorientation grounded in kitsch. A top pick for me.</td>', 'Stunning. Confusion and disorientation grounded in kitsch. A top pick for me.', '2015-04-24 11:54:15.000000', NULL, 1),
(7345008, 1148083, 115814, '<td valign="top">You''ve taken what''s becoming a cliche light painting technique and made it stand out with a strong sense of composition and exceptional exposure control. Cool.</td>', 'You''ve taken what''s becoming a cliche light painting technique and made it stand out with a strong sense of composition and exceptional exposure control. Cool.', '2015-04-24 11:55:51.000000', NULL, 1),
(7345009, 1148114, 115814, '<td valign="top">Strong composition, highly engaging, blur everywhere but right where it matters. Nice!</td>', 'Strong composition, highly engaging, blur everywhere but right where it matters. Nice!', '2015-04-24 11:57:23.000000', NULL, 1),
(7345010, 1148128, 115814, '<td valign="top">You''ve taken what''s becoming a cliche light painting technique and made it stand out with a strong sense of composition and exceptional exposure control. I particularly like the gradient color of the background sky.</td>', 'You''ve taken what''s becoming a cliche light painting technique and made it stand out with a strong sense of composition and exceptional exposure control. I particularly like the gradient color of the background sky.', '2015-04-24 11:58:41.000000', NULL, 1),
(7345012, 1148079, 115814, '<td valign="top">A particularly strong match of technique and subject.</td>', 'A particularly strong match of technique and subject.', '2015-04-24 12:00:46.000000', NULL, 1),
(7345014, 1148066, 115814, '<td valign="top">Among my top picks this round. The use (I presume) of a gradient color filter here serve well to isolate the subject and create an even more ethereal effect that the motion and panning. Kudos!</td>', 'Among my top picks this round. The use (I presume) of a gradient color filter here serve well to isolate the subject and create an even more ethereal effect that the motion and panning. Kudos!', '2015-04-24 12:02:33.000000', NULL, 1),
